function uiRender(B, LANGS) {
  B = B || {};
  LANGS = LANGS || {};
  const T = B.t || {};
  const loc = B.locale || 'en-GB';
  // fn_ui_texts liefert fuer einen fehlenden Key den Key selbst -> das zaehlt hier als "nicht vorhanden".
  const has = (k) => Object.prototype.hasOwnProperty.call(T, k) && T[k] !== k;
  const t = (k) => (has(k) ? T[k] : String(k));
  const empty = has('core.fmt.empty') ? T['core.fmt.empty'] : '—';
  const isEmpty = (v) => v === null || v === undefined || v === '';
  // Platzhalter in EINEM Durchlauf: einfache Werte unveraendert (auch '' fuer optionale Zusaetze wie die Einheit),
  // nur typisierte Werte ({kind: money|date|enum|...}) laufen durch val(); null/undefined -> ''. Ein FEHLENDER
  // Parameter zaehlt wie undefined: n8n verwirft undefined-Felder beim Speichern des Summary-Objekts, sonst stuende
  // Rohtext wie "{isin}" auf der Karte (Owner 2026-10-22). Vertippte Parameter-Namen faengt der Build
  // (Assert-HitlTplParams in New-HitlLine/New-HitlNote/New-HitlSummary).
  function fill(txt, params) {
    return String(txt).replace(/\{(\w+)\}/g, (m, n) => {
      if (!params || !Object.prototype.hasOwnProperty.call(params, n)) return '';
      const p = params[n];
      if (p === null || p === undefined) return '';
      return (typeof p === 'object') ? val(p) : String(p);
    });
  }
  // sign = true (core.fn_ui_money p_sign): '+' vor positive Betraege (Gewinn seit Kauf); negative tragen ihr Minus ohnehin.
  // digits = 0 (core.fn_ui_money p_whole): ganze Einheiten fuer Schaetzwerte; der Wert selbst bleibt genau (gerundet nur hier).
  function money(v, c, sign, digits) {
    if (isEmpty(v)) return empty;
    const n = Number(v);
    if (!isFinite(n)) return String(v);
    const plus = (sign === true && n > 0) ? '+' : '';
    // Ohne gueltigen Waehrungscode KEIN stilles EUR (ein USD-Betrag sahe sonst wie Euro aus): Zahl + Rohcode.
    const whole = (digits === 0);
    if (!(typeof c === 'string' && /^[A-Za-z]{3}$/.test(c))) return plus + num(v, whole ? 0 : 2) + (isEmpty(c) ? '' : ' ' + String(c));
    const cur = c.toUpperCase();
    try { return plus + (whole ? Number(n).toLocaleString(loc,{style:'currency',currency:(/^[A-Za-z]{3}$/.test(cur)?cur:'EUR'),currencyDisplay:'narrowSymbol',minimumFractionDigits:0,maximumFractionDigits:0}) : Number(n).toLocaleString(loc,{style:'currency',currency:(/^[A-Za-z]{3}$/.test(cur)?cur:'EUR'),currencyDisplay:'narrowSymbol'})); } catch (e) { return plus + String(v) + ' ' + cur; }
  }
  // B.date_short = {from, to} (nur die Mini-App, core.fn_app_screen): ein ISO-Datum im Fenster [from, to) ohne Jahr
  // (String-Vergleich, die App rechnet kein Datum); Chat/HITL/Cron setzen es nie -> dort immer mit Jahr.
  const DS = (B.date_short && typeof B.date_short.from === 'string' && typeof B.date_short.to === 'string') ? B.date_short : null;
  function date(v) {
    if (isEmpty(v)) return empty;
    const m = DS ? /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(v)) : null;
    if (m && String(v) >= DS.from && String(v) < DS.to) {
      try { return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])).toLocaleDateString(loc, { timeZone: 'UTC', month: '2-digit', day: '2-digit' }); }
      catch (e) { /* weiter mit Jahr */ }
    }
    try { return ((m) => m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])).toLocaleDateString(loc, {timeZone:'UTC', year:'numeric', month:'2-digit', day:'2-digit'}) : String(v))(/^(\d{4})-(\d{2})-(\d{2})/.exec(String(v))); } catch (e) { return String(v); }
  }
  // {kind:'month', value:'YYYY-MM'} (core.fn_ui_month): 2-stelliger Monat + Jahr im Locale (de „04.2027“), immer mit Jahr.
  // Aus dem vollen Datum des Locales ohne den Tag gebaut: Intl liefert fuer {month, year} allein in de „04/2027“
  // (Abnahme 2026-10-31); so folgt der Trenner dem gewohnten Datum (de „04.2027“, en-GB „04/2027“, ko „2027. 04.“).
  // style 'long' (core.fn_ui_month(d, true)): Monatsname, das Jahr nur ausserhalb des Kurz-Fensters wie bei date()
  // („Gehen ab im November“ / „… im November 2027“).
  function month(v, style) {
    if (isEmpty(v)) return empty;
    const m = /^(\d{4})-(\d{2})$/.exec(String(v));
    if (!m) return String(v);
    if (style === 'long') {
      const short = DS && String(v) >= DS.from.slice(0, 7) && String(v) < DS.to.slice(0, 7);
      try { return new Date(Date.UTC(+m[1], +m[2] - 1, 1)).toLocaleDateString(loc, short ? { timeZone: 'UTC', month: 'long' } : { timeZone: 'UTC', month: 'long', year: 'numeric' }); }
      catch (e) { return String(v); }
    }
    try {
      const parts = new Intl.DateTimeFormat(loc, { timeZone: 'UTC', day: '2-digit', month: '2-digit', year: 'numeric' })
        .formatToParts(new Date(Date.UTC(+m[1], +m[2] - 1, 1)));
      const d = parts.findIndex((p) => p.type === 'day');
      if (d < 0) return String(v);
      if (d === 0) parts.splice(0, 2); else parts.splice(d - 1, 2);
      return parts.map((p) => p.value).join('');
    } catch (e) { return String(v); }
  }
  // Nachkommastellen, die der Wert selbst traegt (ohne Null-Schwanz der DB, z. B. numeric(18,8) "10.00000000" -> 0).
  function decimals(v) {
    const s = String(v).trim();
    const e = s.match(/^-?\d+(?:\.(\d+))?e-(\d+)$/i);
    if (e) return Math.min(20, (e[1] || '').length + Number(e[2]));
    const m = s.match(/\.(\d+)$/);
    return m ? Math.min(20, m[1].replace(/0+$/, '').length) : 0;
  }
  // digits < 0 = so viele Stellen wie der Wert hat (Stueckzahlen: Krypto bis 8 Stellen, nie gerundet).
  function num(v, digits, sign) {
    if (isEmpty(v)) return empty;
    const n = Number(v);
    if (!isFinite(n)) return String(v);
    const d = (Number(digits) < 0) ? decimals(v) : Math.max(0, Math.min(6, Number(digits) || 0));
    try { return n.toLocaleString(loc, { minimumFractionDigits: d, maximumFractionDigits: d, signDisplay: sign ? 'exceptZero' : 'auto' }); }
    catch (e) { return String(v); }
  }
  function val(x) {
    if (isEmpty(x)) return empty;
    if (typeof x !== 'object') return String(x);
    if (Array.isArray(x)) return x.length ? x.map(val).join(', ') : empty;
    const v = x.value;
    switch (x.kind) {
      case 'money': return money(v, x.currency, x.sign, x.digits);
      case 'date': return date(v);
      case 'month': return month(v, x.style);
      case 'number': return num(v, x.digits, x.sign);
      case 'enum': {
        if (isEmpty(v)) return empty;
        const k = String(x.enum) + '.' + String(v).toLowerCase().replace(/[^a-z0-9_]+/g, '_');
        return has(k) ? T[k] : String(v);
      }
      case 'bool': return (v === true || v === 'true') ? t('core.fmt.yes')
        : ((v === false || v === 'false') ? t('core.fmt.no') : empty);
      case 'language': return isEmpty(v) ? empty : (LANGS[v] || String(v));
      case 'key': return isEmpty(v) ? empty : (has(v) ? T[v] : (x.fallback || String(v)));
      case 'tpl': return isEmpty(v) ? empty : fill(t(v), x.params);
      case 'removed': return t('core.fmt.removed');
      case 'list': return (Array.isArray(v) && v.length) ? v.map(val).join(', ') : empty;
      default: return isEmpty(v) ? empty : (Array.isArray(v) ? v.join(', ') : String(v));
    }
  }
  function msg(parts) {
    return (Array.isArray(parts) ? parts : [parts]).filter((p) => !isEmpty(p)).map(val).join(' ');
  }
  function lines(ls) {
    return (Array.isArray(ls) ? ls : []).map((l) => (l === null || l === undefined) ? ''
      : (Array.isArray(l) ? msg(l) : val(l))).join('\n');
  }
  return { T, loc, has, t, empty, isEmpty, fill, money, date, num, val, msg, lines };
}function bankTodoMessage(U, g, isOwner) {
  const bank = g.bank || '';
  const head = g.nudge ? (bank ? 'finance.bank_todo.nudge' : 'finance.bank_todo.nudge_generic')
                       : (bank ? 'finance.bank_todo.intro' : 'finance.bank_todo.intro_generic');
  const holder = (isOwner && g.holder_name) ? ' (' + g.holder_name + ')' : '';
  const L = [U.fill(U.t(head), { bank, holder }), ''];
  (Array.isArray(g.items) ? g.items : []).forEach((it, i) => L.push((i + 1) + '. ' + U.msg(it.line)));
  L.push('', U.t('finance.bank_todo.howto'));
  return { message: L.join('\n'), btn_done: U.fill(U.t(bank ? 'finance.bank_todo.btn_done' : 'finance.bank_todo.btn_done_generic'), { bank }),
           data: 'btodo:' + g.first_id + ':' + g.max_id, btn_off: U.t('core.reminders.btn_off') };
}const groups = JSON.parse($input.first().json.groups || '[]');
const U = uiRender(JSON.parse($input.first().json.ui || '{}'));
if (!Array.isArray(groups) || groups.length === 0) { return [{ json: { nothing: true } }]; }
return groups.map((g) => ({ json: bankTodoMessage(U, g, true) }));
